<?php
require __DIR__ . '/bootstrap.php'; require_login();
$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT l.*,u.name assigned_name,c.name creator_name FROM leads l LEFT JOIN users u ON u.id=l.assigned_to LEFT JOIN users c ON c.id=l.created_by WHERE l.id=?');$stmt->execute([$id]);$lead=$stmt->fetch();if(!$lead){http_response_code(404);exit('Lead not found.');}
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='status'){$status=$_POST['status']??'';$allowed=['New','Contacted','Qualified','Documents Pending','Submitted','Sanctioned','Disbursed','Rejected','Closed'];if(in_array($status,$allowed,true)&&$status!==$lead['status']){$up=$pdo->prepare('UPDATE leads SET status=? WHERE id=?');$up->execute([$status,$id]);log_activity($pdo,$id,current_user()['id'],'Status changed',$lead['status'].' → '.$status);flash('Pipeline status updated.');header('Location: lead-view.php?id='.$id);exit;}}
 if($action==='activity'){$desc=trim($_POST['description']??'');if($desc!==''){$up=$pdo->prepare('INSERT INTO activities (lead_id,user_id,activity_type,description) VALUES (?,?,?,?)');$up->execute([$id,current_user()['id'],'Note',$desc]);flash('Activity note added.');header('Location: lead-view.php?id='.$id);exit;}}
}
$act=$pdo->prepare('SELECT a.*,u.name FROM activities a LEFT JOIN users u ON u.id=a.user_id WHERE lead_id=? ORDER BY created_at DESC LIMIT 100');$act->execute([$id]);$activities=$act->fetchAll();$flash=get_flash();require __DIR__.'/partials/header.php';
?>
<div class="page-heading"><div><p class="eyebrow">LEAD #<?=str_pad((string)$id,5,'0',STR_PAD_LEFT)?></p><h1><?=h($lead['full_name'])?></h1><p class="muted"><?=h($lead['loan_type'])?> · Created <?=h(date('d M Y',strtotime($lead['created_at'])))?></p></div><div class="heading-actions"><a class="btn secondary" href="leads.php">← All leads</a><a class="btn primary" href="lead-form.php?id=<?=$id?>">Edit lead</a></div></div>
<?php if($flash):?><div class="alert <?=h($flash['type'])?>"><?=h($flash['message'])?></div><?php endif;?>
<div class="detail-layout"><div class="detail-main"><section class="panel"><div class="panel-heading"><div><h2>Application snapshot</h2><p class="muted">Current lead status and loan request.</p></div><span class="status status-<?=h(strtolower(str_replace(' ','-',$lead['status'])))?>"><?=h($lead['status'])?></span></div><div class="detail-metrics"><div><small>Requested amount</small><strong><?=money($lead['requested_amount'])?></strong></div><div><small>Monthly income</small><strong><?=money($lead['monthly_income'])?></strong></div><div><small>Lead source</small><strong><?=h($lead['source'])?></strong></div></div><form method="post" class="inline-status"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="status"><label>Update pipeline status<select name="status"><?php foreach(['New','Contacted','Qualified','Documents Pending','Submitted','Sanctioned','Disbursed','Rejected','Closed'] as $s):?><option <?=($lead['status']===$s?'selected':'')?> value="<?=h($s)?>"><?=h($s)?></option><?php endforeach;?></select></label><button class="btn secondary">Update status</button></form></section>
<section class="panel"><div class="panel-heading"><div><h2>Activity timeline</h2><p class="muted">Notes and status changes for this lead.</p></div></div><form method="post" class="activity-form"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="activity"><textarea name="description" rows="2" required maxlength="5000" placeholder="Add a call summary, customer update or next step…"></textarea><button class="btn primary">Add note</button></form><div class="timeline"><?php if(!$activities):?><div class="empty">No activity recorded yet.</div><?php endif;?><?php foreach($activities as $a):?><div class="timeline-item"><span class="timeline-marker"></span><div><div class="timeline-head"><strong><?=h($a['activity_type'])?></strong><small><?=h($a['name']??'System')?> · <?=h(date('d M Y, g:i A',strtotime($a['created_at'])))?></small></div><p><?=nl2br(h($a['description']))?></p></div></div><?php endforeach;?></div></section></div>
<aside class="detail-side"><section class="panel"><h2>Customer details</h2><div class="info-list"><div><small>Mobile</small><strong><?=h($lead['phone'])?></strong></div><div><small>Email</small><strong><?=h($lead['email']?:'Not provided')?></strong></div><div><small>City</small><strong><?=h($lead['city']?:'Not provided')?></strong></div><div><small>Employment</small><strong><?=h($lead['employment_type'])?></strong></div><div><small>Consent status</small><strong><?=h($lead['consent_status'])?></strong></div><div><small>Assigned to</small><strong><?=h($lead['assigned_name']?:'Unassigned')?></strong></div><div><small>Next follow-up</small><strong><?=h($lead['next_follow_up']?:'Not scheduled')?></strong></div></div></section><section class="panel"><h2>Notes</h2><p class="note-text"><?=nl2br(h($lead['notes']?:'No notes added.'))?></p></section><section class="notice-card"><strong>Eligibility reminder</strong><p>This record tracks an enquiry only. It does not represent lender approval or a verified credit assessment.</p></section></aside></div>
